        assertThat(Calculator.add(a, b)).isEqualTo(expected);
    }

    @ParameterizedTest
    @MethodSource("orderTestCases") // references the factory method below
    void calculateTotal_shouldApplyDiscount(BigDecimal price, String code,
                                             BigDecimal expected) {
        assertThat(pricingService.calculateTotal(price, code))
                .isEqualByComparingTo(expected);
    }

    static Stream<Arguments> orderTestCases() {
        return Stream.of(
                Arguments.of(BigDecimal.valueOf(100), "HALF", BigDecimal.valueOf(50)),
                Arguments.of(BigDecimal.valueOf(200), "10OFF", BigDecimal.valueOf(190)),
